<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,reactive,ref} from 'vue'
import {ElMessage} from 'element-plus'
import {fetchKnowledgeCardAttachment,fetchKnowledgeCardFrequency,fetchKnowledgeCards,updateKnowledgeCardState,type Frequency,type KnowledgeCard} from '../../api/student/knowledgeCards'
import ScientificText from '../../components/question/ScientificText.vue'
import StudentAiLearningPanel from '../../components/student/StudentAiLearningPanel.vue'
const cards=ref<KnowledgeCard[]>([]),selected=ref<KnowledgeCard>(),frequency=ref<Frequency[]>([]),loading=ref(false)
const imageSources=ref<Record<number,string>>({})
const filters=reactive({subjectId:undefined as number|undefined,knowledgePointId:undefined as number|undefined,type:'',favorite:undefined as boolean|undefined,mastery:''})
const types=[['POINT','考点'],['FORMULA','公式'],['CHEMICAL_EQUATION','方程式'],['SECONDARY_CONCLUSION','二级结论'],['INSTRUMENT','实验器具'],['MNEMONIC','口诀'],['TABLE','表格'],['NOTE','笔记']]
const subjects=computed(()=>[...new Map(cards.value.map(c=>[c.subjectId,{id:c.subjectId,name:c.subjectName}])).values()])
const points=computed(()=>[...new Map(cards.value.flatMap(c=>c.knowledgePoints).map(p=>[p.id,p])).values()])
async function load(){loading.value=true;try{cards.value=await fetchKnowledgeCards({subjectId:filters.subjectId,knowledgePointId:filters.knowledgePointId,type:filters.type||undefined,favorite:filters.favorite,mastery:filters.mastery||undefined});if(selected.value&&!cards.value.some(c=>c.id===selected.value!.id))selected.value=undefined}catch{ElMessage.error('知识卡片加载失败。')}finally{loading.value=false}}
function clearImages(){Object.values(imageSources.value).forEach(URL.revokeObjectURL);imageSources.value={}}
async function open(card:KnowledgeCard){clearImages();selected.value=card;frequency.value=await fetchKnowledgeCardFrequency(card.id);for(const item of card.attachments){try{imageSources.value[item.id]=URL.createObjectURL(await fetchKnowledgeCardAttachment(card.id,item.id))}catch{ElMessage.warning(`${item.name} 暂不可读取。`)}}}
async function state(card:KnowledgeCard,favorite=card.favorite,mastery=card.mastery){selected.value=await updateKnowledgeCardState(card.id,{favorite,mastery});cards.value=cards.value.map(c=>c.id===card.id?selected.value!:c)}
onMounted(load)
onBeforeUnmount(clearImages)
</script>
<template><main class="card-library"><header><div><p>REVIEWED SCIENCE CARDS</p><h1>知识卡片与公式口诀</h1><span>所有可见内容均已人工审核；“近年高频”只来自满足来源条件的真题统计。</span></div></header><section class="filters"><el-select v-model="filters.subjectId" clearable placeholder="学科"><el-option v-for="s in subjects" :key="s.id" :label="s.name" :value="s.id"/></el-select><el-select v-model="filters.knowledgePointId" clearable filterable placeholder="知识点"><el-option v-for="p in points" :key="p.id" :label="p.path" :value="p.id"/></el-select><el-select v-model="filters.type" clearable placeholder="卡片类型"><el-option v-for="t in types" :key="t[0]" :label="t[1]" :value="t[0]"/></el-select><el-select v-model="filters.mastery" clearable placeholder="掌握状态"><el-option label="学习中" value="LEARNING"/><el-option label="已掌握" value="MASTERED"/></el-select><el-button type="primary" @click="load">筛选</el-button></section><section v-loading="loading" class="card-grid"><article v-for="card in cards" :key="card.id" tabindex="0" @click="open(card)" @keydown.enter="open(card)"><div><el-tag effect="plain">{{types.find(t=>t[0]===card.type)?.[1]}}</el-tag><span>{{card.subjectName}}</span></div><h2>{{card.title}}</h2><ScientificText :content="card.content"/><small>{{card.knowledgePoints.map(p=>p.path).join(' · ')}}</small><footer><el-button link @click.stop="state(card,!card.favorite,card.mastery)">{{card.favorite?'取消收藏':'收藏'}}</el-button><el-button link @click.stop="state(card,card.favorite,card.mastery==='MASTERED'?'LEARNING':'MASTERED')">{{card.mastery==='MASTERED'?'改为学习中':'标记已掌握'}}</el-button></footer></article><el-empty v-if="!cards.length" description="当前任课范围暂无符合条件的已审核卡片"/></section><el-drawer v-model="selected" size="min(720px,100%)" title="知识卡片详情"><template v-if="selected"><h2>{{selected.title}}</h2><p>{{selected.subjectName}} · {{selected.knowledgePoints.map(p=>p.path).join('；')}}</p><ScientificText :content="selected.content"/><section v-if="selected.latex"><h3>公式 / 科学表达</h3><ScientificText :content="selected.latex"/></section><section v-if="selected.applicableConditions"><h3>适用条件</h3><ScientificText :content="selected.applicableConditions"/></section><section v-if="selected.derivation"><h3>含义与推导</h3><ScientificText :content="selected.derivation"/></section><section v-if="selected.example"><h3>简单例子</h3><ScientificText :content="selected.example"/></section><section v-if="selected.commonMistake"><h3>常见误区</h3><ScientificText :content="selected.commonMistake"/></section><section v-if="selected.mnemonic"><h3>记忆口诀</h3><ScientificText :content="selected.mnemonic"/></section><figure v-for="image in selected.attachments" :key="image.id"><img v-if="imageSources[image.id]" :src="imageSources[image.id]" :alt="image.name"><figcaption>{{image.name}}</figcaption></figure><section class="frequency"><article v-for="f in frequency" :key="f.window"><strong>{{f.window}}</strong><span>{{f.occurrences}} 题 · {{f.paperCount}} 份试卷</span><p v-if="f.sampleNotice">{{f.sampleNotice}}</p></article></section><p class="source">来源：<a v-if="selected.sourceUrl" :href="selected.sourceUrl" target="_blank" rel="noopener noreferrer">{{selected.sourceName}}</a><span v-else>{{selected.sourceName||'项目自编总结'}}</span> · 权利状态 {{selected.rightsStatus}}</p><StudentAiLearningPanel :knowledge-card-id="selected.id"/><el-alert title="生成练习将复用统一候选题 Schema；提交题库时仍为 PENDING，必须人工审核。" type="info" :closable="false"/><el-button type="primary" disabled>生成练习（需启用文本 Provider）</el-button></template></el-drawer></main></template>
<style scoped>.card-library{max-width:1280px;margin:auto;padding:28px}.card-library header{padding:28px;border-radius:24px;background:linear-gradient(135deg,#e7fbff,#f6f1ff)}.card-library header p{letter-spacing:.16em;color:#177b8f}.filters{display:flex;flex-wrap:wrap;gap:10px;margin:20px 0}.filters .el-select{width:190px}.card-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:16px}.card-grid>article{display:flex;flex-direction:column;gap:10px;padding:20px;border:1px solid var(--el-border-color-lighter);border-radius:18px;background:white;box-shadow:0 10px 30px rgba(23,72,88,.07);cursor:pointer}.card-grid>article:focus-visible{outline:3px solid var(--el-color-primary-light-5)}.card-grid article>div,.card-grid footer{display:flex;justify-content:space-between}.card-grid h2{margin:0}.card-grid small{color:var(--el-text-color-secondary)}figure img{max-width:100%;border-radius:14px}.frequency{display:grid;grid-template-columns:1fr 1fr;gap:12px}.frequency article{display:grid;padding:12px;border-radius:12px;background:var(--el-fill-color-light)}.source{color:var(--el-text-color-secondary)}@media(max-width:640px){.card-library{padding:14px}.filters .el-select{width:100%}.frequency{grid-template-columns:1fr}}</style>
